import { DomainError } from "./DomainError";
import { OrderLine } from "./OrderLine";
import { Product } from "./Product";
import { ProductRepository } from "./ProductRepository";

export class StockService {
  constructor(private readonly products: ProductRepository) {}

  /** Reserves every line or none of them. */
  reserve(lines: readonly OrderLine[]): void {
    const resolved = this.resolve(lines);
    const short = resolved.filter(({ product, line }) => !product.canReserve(line.quantity));
    if (short.length > 0) {
      const detail = short
        .map(({ product, line }) => `${product.id} (requested ${line.quantity}, available ${product.available})`)
        .join(", ");
      throw new DomainError("conflict", `Insufficient stock for: ${detail}`);
    }
    this.apply(resolved, (product, quantity) => product.reserve(quantity));
  }

  release(lines: readonly OrderLine[]): void {
    this.apply(this.resolve(lines), (product, quantity) => product.release(quantity));
  }

  dispatch(lines: readonly OrderLine[]): void {
    this.apply(this.resolve(lines), (product, quantity) => product.dispatch(quantity));
  }

  private resolve(lines: readonly OrderLine[]): { product: Product; line: OrderLine }[] {
    return lines.map((line) => {
      const product = this.products.findById(line.productId);
      if (!product) {
        throw new DomainError("not_found", `Product ${line.productId} does not exist`);
      }
      return { product, line };
    });
  }

  private apply(
    resolved: { product: Product; line: OrderLine }[],
    change: (product: Product, quantity: number) => void,
  ): void {
    for (const { product, line } of resolved) {
      change(product, line.quantity);
      this.products.save(product);
    }
  }
}

